sp_widget.client_script:
api.controller = function($scope, $location) {

    var c = this;


    /* ============================================================
       NEXORA — PLACEMENT DRIVE DETAILS
       CLIENT CONTROLLER

       Works with:
       - Student
       - Placement Officer
       - Placement Admin
       - Interviewer
       - Company HR
       - Admin
       ============================================================ */


    /* ============================================================
       01. INITIAL STATE
       ============================================================ */

    c.loading = false;
    c.actionLoading = false;

    c.showActionMessage = false;
    c.actionMessage = '';
    c.actionType = '';

    c.showApplyConfirm = false;

    c.currentSection = 'overview';


    /* ============================================================
       02. SAFE VALUE HELPER
       ============================================================ */

    function normalize(value) {

        return (value || '')
            .toString()
            .trim()
            .toLowerCase();

    }


    /* ============================================================
       03. GET DRIVE ID
       ============================================================ */

    c.getDriveId = function() {

        if (
            c.data &&
            c.data.drive &&
            c.data.drive.sysId
        ) {

            return c.data.drive.sysId;

        }

        var params =
            new URLSearchParams(
                window.location.search
            );

        return (
            params.get('sys_id') ||
            params.get('id') ||
            ''
        );

    };


    /* ============================================================
       04. INITIALIZATION
       ============================================================ */

    c.$onInit = function() {

        c.refreshView();

    };


    /* ============================================================
       05. REFRESH VIEW STATE
       ============================================================ */

    c.refreshView = function() {

        if (
            !c.data ||
            !c.data.drive
        ) {

            return;

        }

        /*
         * Determine current drive state
         */

        c.driveStatus =
            normalize(
                c.data.drive.status
            );

        c.isActive =
            !!c.data.drive.isActive;

        c.isClosed =
            !!c.data.drive.isClosed;

        c.deadlinePassed =
            !!c.data.drive.deadlinePassed;


        /*
         * Student application state
         */

        c.hasApplied =
            !!c.data.hasApplied;

        c.studentAction =
            c.data.studentAction ||
            'apply';


        /*
         * Permission state
         */

        c.canManage =
            !!c.data.canManage;

        c.canInterview =
            !!c.data.canInterview;

        c.isStudent =
            !!c.data.isStudent;


        /*
         * Role label
         */

        c.roleLabel =
            c.data.roleLabel ||
            'Student';


        /*
         * Company initial
         */

        if (
            !c.data.drive.companyInitial
        ) {

            var company =
                c.data.drive.company ||
                'N';

            c.data.drive.companyInitial =
                company
                    .substring(0, 1)
                    .toUpperCase();

        }

    };


    /* ============================================================
       06. BACK TO PLACEMENT DRIVES
       ============================================================ */

    c.goBack = function() {

        window.location.href =
            '?id=placement_drives';

    };


    /* ============================================================
       07. OPEN SECTION
       ============================================================ */

    c.openSection = function(section) {

        c.currentSection =
            section || 'overview';

    };


    /* ============================================================
       08. STUDENT — APPLY
       ============================================================ */

    c.startApplication = function() {

        if (
            !c.isStudent
        ) {

            return;

        }


        /*
         * Already applied
         */

        if (
            c.hasApplied
        ) {

            c.showMessage(
                'You have already submitted an application for this placement drive.',
                'info'
            );

            return;

        }


        /*
         * Deadline passed
         */

        if (
            c.deadlinePassed
        ) {

            c.showMessage(
                'The registration deadline for this placement drive has passed.',
                'warning'
            );

            return;

        }


        /*
         * Drive closed
         */

        if (
            c.isClosed ||
            !c.isActive
        ) {

            c.showMessage(
                'Applications are currently closed for this placement drive.',
                'warning'
            );

            return;

        }


        /*
         * Open confirmation
         */

        c.showApplyConfirm = true;

    };


    /* ============================================================
       09. CLOSE APPLY CONFIRMATION
       ============================================================ */

    c.closeApplyConfirmation = function() {

        c.showApplyConfirm = false;

    };


    /* ============================================================
       10. CONFIRM APPLICATION
       ============================================================ */

    c.confirmApplication = function() {

        if (
            c.actionLoading
        ) {

            return;

        }


        c.actionLoading = true;


        /*
         * Send action to Server Script.
         *
         * IMPORTANT:
         * The Server Script must contain the application
         * creation logic for this action.
         */

        c.server.get({

            action: 'apply',
            drive_id: c.getDriveId()

        }).then(function(response) {

            c.actionLoading = false;

            c.showApplyConfirm = false;


            if (
                response &&
                response.data
            ) {

                /*
                 * Refresh local data
                 */

                angular.extend(
                    c.data,
                    response.data
                );

                c.refreshView();


                if (
                    response.data.success
                ) {

                    c.showMessage(
                        response.data.message ||
                        'Application submitted successfully.',
                        'success'
                    );

                } else {

                    c.showMessage(
                        response.data.message ||
                        'Unable to submit your application.',
                        'error'
                    );

                }

            } else {

                c.showMessage(
                    'Unable to process the application.',
                    'error'
                );

            }

        }, function() {

            c.actionLoading = false;

            c.showApplyConfirm = false;

            c.showMessage(
                'An unexpected error occurred while submitting your application.',
                'error'
            );

        });

    };


    /* ============================================================
       11. SHOW ACTION MESSAGE
       ============================================================ */

    c.showMessage = function(
        message,
        type
    ) {

        c.actionMessage =
            message || '';

        c.actionType =
            type || 'info';

        c.showActionMessage = true;


        /*
         * Automatically hide after 5 seconds
         */

        $scope.$evalAsync(
            function() {

                setTimeout(
                    function() {

                        $scope.$apply(
                            function() {

                                c.showActionMessage =
                                    false;

                            }
                        );

                    },
                    5000
                );

            }
        );

    };


    /* ============================================================
       12. CLOSE MESSAGE
       ============================================================ */

    c.closeMessage = function() {

        c.showActionMessage = false;

    };


    /* ============================================================
       13. MANAGEMENT — EDIT DRIVE
       ============================================================ */

    c.editDrive = function() {

        if (
            !c.canManage
        ) {

            return;

        }


        var driveId =
            c.getDriveId();


        if (!driveId) {

            c.showMessage(
                'Placement drive record could not be identified.',
                'error'
            );

            return;

        }


        /*
         * IMPORTANT:
         *
         * Create a ServiceNow Portal page:
         *
         * placement_drive_edit
         *
         * if you want administrators/officers to edit
         * the drive from the portal.
         */

        window.location.href =
            '?id=placement_drive_edit&sys_id=' +
            encodeURIComponent(
                driveId
            );

    };


    /* ============================================================
       14. MANAGEMENT — APPLICATIONS
       ============================================================ */

    c.manageApplications = function() {

        if (
            !c.canManage
        ) {

            return;

        }


        var driveId =
            c.getDriveId();


        if (!driveId) {

            return;

        }


        window.location.href =
            '?id=placement_applications&drive_id=' +
            encodeURIComponent(
                driveId
            );

    };


    /* ============================================================
       15. MANAGEMENT — INTERVIEWS
       ============================================================ */

    c.manageInterviews = function() {

        if (
            !c.canInterview
        ) {

            return;

        }


        var driveId =
            c.getDriveId();


        if (!driveId) {

            return;

        }


        window.location.href =
            '?id=placement_interviews&drive_id=' +
            encodeURIComponent(
                driveId
            );

    };


    /* ============================================================
       16. MANAGEMENT — STATISTICS
       ============================================================ */

    c.viewStatistics = function() {

        if (
            !c.canManage
        ) {

            return;

        }


        var driveId =
            c.getDriveId();


        if (!driveId) {

            return;

        }


        window.location.href =
            '?id=placement_statistics&drive_id=' +
            encodeURIComponent(
                driveId
            );

    };


    /* ============================================================
       17. OPERATION HANDLER
       ============================================================ */

    c.executeOperation = function(
        operation
    ) {

        if (
            !operation
        ) {

            return;

        }


        switch (
            normalize(
                operation.action ||
                operation.type
            )
        ) {

            case 'edit':

                c.editDrive();

                break;


            case 'applications':

                c.manageApplications();

                break;


            case 'interviews':

                c.manageInterviews();

                break;


            case 'statistics':

                c.viewStatistics();

                break;


            default:

                c.showMessage(
                    'This operation is not available.',
                    'warning'
                );

                break;

        }

    };


    /* ============================================================
       18. STATUS HELPERS
       ============================================================ */

    c.getStatusClass = function(
        status
    ) {

        var value =
            normalize(status);


        if (
            value === 'active' ||
            value === 'open' ||
            value === 'open for applications'
        ) {

            return 'is-active';

        }


        if (
            value === 'upcoming'
        ) {

            return 'is-upcoming';

        }


        if (
            value === 'completed'
        ) {

            return 'is-completed';

        }


        if (
            value === 'closed'
        ) {

            return 'is-closed';

        }


        if (
            value === 'cancelled' ||
            value === 'canceled'
        ) {

            return 'is-cancelled';

        }


        return 'is-default';

    };


    /* ============================================================
       19. STATUS ICON
       ============================================================ */

    c.getStatusIcon = function(
        status
    ) {

        var value =
            normalize(status);


        if (
            value === 'active' ||
            value === 'open'
        ) {

            return 'fa-unlock';

        }


        if (
            value === 'upcoming'
        ) {

            return 'fa-clock-o';

        }


        if (
            value === 'completed'
        ) {

            return 'fa-check-circle';

        }


        if (
            value === 'closed'
        ) {

            return 'fa-lock';

        }


        if (
            value === 'cancelled' ||
            value === 'canceled'
        ) {

            return 'fa-times-circle';

        }


        return 'fa-circle-o';

    };


    /* ============================================================
       20. APPLICATION STATUS CLASS
       ============================================================ */

    c.getApplicationStatusClass =
        function(status) {

            var value =
                normalize(status);


            if (
                value === 'selected' ||
                value === 'offered'
            ) {

                return 'status-success';

            }


            if (
                value === 'shortlisted' ||
                value === 'interview scheduled' ||
                value === 'interview'
            ) {

                return 'status-progress';

            }


            if (
                value === 'rejected'
            ) {

                return 'status-danger';

            }


            if (
                value === 'pending' ||
                value === 'applied'
            ) {

                return 'status-pending';

            }


            return 'status-default';

        };


    /* ============================================================
       21. JOURNEY STATE
       ============================================================ */

    c.isJourneyComplete = function(
        item
    ) {

        return !!(
            item &&
            item.complete
        );

    };


    /* ============================================================
       22. TIMELINE STATE
       ============================================================ */

    c.getTimelineClass = function(
        item
    ) {

        if (
            !item
        ) {

            return 'timeline-pending';

        }


        switch (
            normalize(
                item.state
            )
        ) {

            case 'complete':

                return 'timeline-complete';


            case 'active':

                return 'timeline-active';


            default:

                return 'timeline-pending';

        }

    };


    /* ============================================================
       23. COUNT PERCENTAGE
       ============================================================ */

    c.getPercentage = function(
        value
    ) {

        var total =
            parseInt(
                c.data &&
                c.data.pipeline &&
                c.data.pipeline.applied,
                10
            ) || 0;


        var current =
            parseInt(
                value,
                10
            ) || 0;


        if (
            total <= 0
        ) {

            return 0;

        }


        var percentage =
            (
                current /
                total
            ) * 100;


        return Math.round(
            percentage
        );

    };


    /* ============================================================
       24. FORMAT COUNT
       ============================================================ */

    c.formatCount = function(
        value
    ) {

        var number =
            parseInt(
                value,
                10
            );


        if (
            isNaN(number)
        ) {

            return '0';

        }


        return number
            .toLocaleString();

    };


    /* ============================================================
       25. MANAGEMENT ACCESS CHECK
       ============================================================ */

    c.hasManagementAccess =
        function() {

            return (
                !!c.data &&
                (
                    !!c.data.canManage ||
                    !!c.data.isAdmin
                )
            );

        };


    /* ============================================================
       26. INTERVIEW ACCESS CHECK
       ============================================================ */

    c.hasInterviewAccess =
        function() {

            return (
                !!c.data &&
                (
                    !!c.data.canInterview ||
                    !!c.data.isAdmin
                )
            );

        };


    /* ============================================================
       27. STUDENT APPLY BUTTON TEXT
       ============================================================ */

    c.getApplyButtonText =
        function() {

            if (
                c.hasApplied
            ) {

                return 'Application Submitted';

            }


            if (
                c.deadlinePassed
            ) {

                return 'Registration Closed';

            }


            if (
                c.isClosed ||
                !c.isActive
            ) {

                return 'Applications Closed';

            }


            return 'Apply for this Drive';

        };


    /* ============================================================
       28. STUDENT APPLY BUTTON STATE
       ============================================================ */

    c.canApply = function() {

        return (
            c.isStudent &&
            !c.hasApplied &&
            !c.deadlinePassed &&
            !c.isClosed &&
            c.isActive
        );

    };


    /* ============================================================
       29. ROLE BADGE
       ============================================================ */

    c.getRoleClass = function() {

        if (
            !c.data
        ) {

            return 'role-student';

        }


        if (
            c.data.isAdmin
        ) {

            return 'role-admin';

        }


        if (
            c.data.isPlacementAdmin
        ) {

            return 'role-placement-admin';

        }


        if (
            c.data.isPlacementOfficer
        ) {

            return 'role-placement-officer';

        }


        if (
            c.data.isCompanyHR
        ) {

            return 'role-company-hr';

        }


        if (
            c.data.isInterviewer
        ) {

            return 'role-interviewer';

        }


        return 'role-student';

    };


    /* ============================================================
       30. WATCH SERVER DATA
       ============================================================ */

    $scope.$watch(
        function() {

            return c.data &&
                   c.data.drive;

        },

        function(newValue) {

            if (
                newValue
            ) {

                c.refreshView();

            }

        },

        true
    );


    /* ============================================================
       31. WATCH ROLE/PERMISSION CHANGES
       ============================================================ */

    $scope.$watchGroup(
        [
            function() {

                return c.data &&
                       c.data.isStudent;

            },

            function() {

                return c.data &&
                       c.data.canManage;

            },

            function() {

                return c.data &&
                       c.data.canInterview;

            }
        ],

        function() {

            c.refreshView();

        }
    );


    /* ============================================================
       32. ESC KEY — CLOSE CONFIRMATION / MESSAGE
       ============================================================ */

    angular.element(
        document
    ).on(
        'keydown.nexoraDrive',
        function(event) {

            if (
                event.key === 'Escape' ||
                event.keyCode === 27
            ) {

                $scope.$applyAsync(
                    function() {

                        c.showApplyConfirm =
                            false;

                        c.showActionMessage =
                            false;

                    }
                );

            }

        }
    );


};

sp_widget.css:
/* ============================================================
   NEXORA — PLACEMENT DRIVE WORKSPACE
   PROFESSIONAL SERVICENOW PORTAL CSS
   ============================================================ */


/* ============================================================
   01. GLOBAL RESET
   ============================================================ */

.nexora-main,
.nexora-main * {
    box-sizing: border-box;
}

.nexora-main {
    width: 100%;
    min-height: 100vh;
    padding: 34px 42px 70px 42px;

    background:
        radial-gradient(
            circle at 85% 8%,
            rgba(255, 107, 91, 0.035),
            transparent 28%
        ),
        #f5f7fa;

    color: #172b3f;

    font-family:
        "Inter",
        "Segoe UI",
        Arial,
        sans-serif;

    overflow-x: hidden;
}


/* ============================================================
   MAIN WORKSPACE
   ============================================================ */

.nx-drive-workspace {
    width: 100%;
    max-width: 1480px;
    margin: 0 auto;
}


/* ============================================================
   02. PAGE TOP BAR
   ============================================================ */

.nx-page-topbar {
    display: flex;
    align-items: center;
    justify-content: space-between;

    margin-bottom: 18px;
    min-height: 34px;
}


/* BACK LINK */

.nx-back-link {
    display: inline-flex;
    align-items: center;
    gap: 10px;

    color: #506579;
    text-decoration: none;

    font-size: 13px;
    font-weight: 600;

    transition:
        color 0.2s ease,
        transform 0.2s ease;
}

.nx-back-link:hover {
    color: #173b57;
    text-decoration: none;
    transform: translateX(-2px);
}

.nx-back-icon {
    width: 29px;
    height: 29px;

    display: flex;
    align-items: center;
    justify-content: center;

    border: 1px solid #dce4eb;
    border-radius: 8px;

    background: #ffffff;

    color: #496176;

    font-size: 11px;

    box-shadow: 0 2px 7px rgba(23, 43, 63, 0.04);
}


/* PAGE CONTEXT */

.nx-page-context {
    display: flex;
    align-items: center;
    gap: 9px;

    color: #8a9aaa;

    font-size: 10px;
    font-weight: 700;

    letter-spacing: 0.7px;
    text-transform: uppercase;
}

.nx-context-dot {
    width: 6px;
    height: 6px;

    border-radius: 50%;

    background: #ff6b5b;

    box-shadow:
        0 0 0 4px rgba(255, 107, 91, 0.08);
}

.nx-context-separator {
    color: #c4cdd5;
}


/* ============================================================
   03. DRIVE HEADER
   ============================================================ */

.nx-drive-header {
    position: relative;

    overflow: hidden;

    border-radius: 18px;

    background:
        linear-gradient(
            120deg,
            #142f46 0%,
            #193b56 46%,
            #204963 100%
        );

    color: #ffffff;

    box-shadow:
        0 14px 35px rgba(20, 47, 70, 0.16),
        0 3px 10px rgba(20, 47, 70, 0.08);

    margin-bottom: 18px;
}


/* BACKGROUND GLOW */

.nx-header-glow {
    position: absolute;

    width: 430px;
    height: 430px;

    right: -160px;
    top: -240px;

    border-radius: 50%;

    background:
        radial-gradient(
            circle,
            rgba(255, 107, 91, 0.20),
            rgba(255, 107, 91, 0) 68%
        );

    pointer-events: none;
}


/* PATTERN */

.nx-header-pattern {
    position: absolute;

    inset: 0;

    opacity: 0.055;

    background-image:
        linear-gradient(
            135deg,
            transparent 25%,
            #ffffff 25%,
            #ffffff 26%,
            transparent 26%
        );

    background-size: 28px 28px;

    pointer-events: none;
}


/* HEADER CONTENT */

.nx-header-content {
    position: relative;
    z-index: 2;

    display: flex;
    align-items: flex-start;
    justify-content: space-between;

    padding: 32px 34px 28px;
}


/* COMPANY AREA */

.nx-company-section {
    display: flex;
    align-items: center;
    gap: 19px;

    min-width: 0;
}


/* COMPANY LOGO */

.nx-company-logo {
    flex-shrink: 0;

    width: 68px;
    height: 68px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 16px;

    background: #ffffff;

    color: #193b56;

    font-size: 24px;
    font-weight: 800;

    box-shadow:
        0 8px 22px rgba(0, 0, 0, 0.15);

    text-transform: uppercase;
}

.nx-company-logo span {
    transform: translateY(-1px);
}


/* COMPANY COPY */

.nx-company-copy {
    min-width: 0;
}

.nx-eyebrow {
    display: flex;
    align-items: center;
    gap: 8px;

    margin-bottom: 7px;

    color: #9eb5c8;

    font-size: 9px;
    font-weight: 800;

    letter-spacing: 1.6px;
}

.nx-eyebrow-line {
    width: 18px;
    height: 2px;

    border-radius: 4px;

    background: #ff6b5b;
}

.nx-company-copy h1 {
    margin: 0;

    color: #ffffff;

    font-size: 29px;
    line-height: 1.15;
    font-weight: 750;

    letter-spacing: -0.5px;
}

.nx-drive-title {
    margin-top: 5px;

    color: #d7e4ed;

    font-size: 13px;
    font-weight: 500;
}

.nx-drive-meta {
    display: flex;
    align-items: center;
    gap: 11px;

    margin-top: 12px;

    color: #9fb5c7;

    font-size: 11px;
    font-weight: 600;
}

.nx-drive-meta i {
    margin-right: 5px;
    color: #7f9bb0;
}

.nx-meta-divider {
    width: 3px;
    height: 3px;

    border-radius: 50%;

    background: #647f93;
}


/* HEADER RIGHT */

.nx-header-status-area {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 22px;

    padding-left: 30px;
}


/* STATUS */

.nx-status-badge {
    display: inline-flex;
    align-items: center;
    gap: 8px;

    padding: 8px 13px;

    border: 1px solid rgba(255, 255, 255, 0.13);
    border-radius: 30px;

    background: rgba(255, 255, 255, 0.08);

    color: #ffffff;

    font-size: 9px;
    font-weight: 800;

    letter-spacing: 0.7px;
    text-transform: uppercase;

    backdrop-filter: blur(8px);
}

.nx-status-indicator {
    width: 7px;
    height: 7px;

    border-radius: 50%;

    background: #ff6b5b;

    box-shadow:
        0 0 0 4px rgba(255, 107, 91, 0.12);
}

.nx-status-closed .nx-status-indicator {
    background: #9baab6;
}

.nx-status-draft .nx-status-indicator {
    background: #f2bd55;
}


/* DRIVE ID */

.nx-header-id {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 4px;
}

.nx-header-id span {
    color: #7994a8;

    font-size: 8px;
    font-weight: 800;

    letter-spacing: 1.2px;
}

.nx-header-id strong {
    max-width: 210px;

    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;

    color: #dbe7ef;

    font-size: 10px;
    font-weight: 600;

    font-family:
        "SFMono-Regular",
        Consolas,
        monospace;
}


/* ============================================================
   HEADER METRICS
   ============================================================ */

.nx-header-metrics {
    position: relative;
    z-index: 2;

    display: grid;
    grid-template-columns: repeat(4, 1fr);

    border-top: 1px solid rgba(255, 255, 255, 0.09);

    background: rgba(7, 27, 43, 0.18);
}

.nx-header-metric {
    display: flex;
    align-items: center;
    gap: 12px;

    min-height: 74px;

    padding: 15px 24px;

    border-right: 1px solid rgba(255, 255, 255, 0.08);
}

.nx-header-metric:last-child {
    border-right: 0;
}

.nx-metric-icon {
    width: 34px;
    height: 34px;

    flex-shrink: 0;

    display: flex;
    align-items: center;
    justify-content: center;

    border: 1px solid rgba(255, 255, 255, 0.10);
    border-radius: 9px;

    background: rgba(255, 255, 255, 0.07);

    color: #9fb8c9;

    font-size: 12px;
}

.nx-header-metric div:last-child {
    min-width: 0;
}

.nx-header-metric span {
    display: block;

    margin-bottom: 4px;

    color: #7995aa;

    font-size: 8px;
    font-weight: 800;

    letter-spacing: 0.9px;
}

.nx-header-metric strong {
    display: block;

    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;

    color: #ffffff;

    font-size: 11px;
    font-weight: 650;
}


/* ============================================================
   04. STUDENT ACTION BAR
   ============================================================ */

.nx-student-actionbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;

    margin-bottom: 22px;
    padding: 15px 18px;

    border: 1px solid #e1e8ee;
    border-radius: 13px;

    background: #ffffff;

    box-shadow:
        0 4px 14px rgba(23, 43, 63, 0.035);
}

.nx-action-message {
    display: flex;
    align-items: center;
    gap: 13px;
}

.nx-action-message-icon {
    width: 37px;
    height: 37px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 10px;

    background: #fff1ef;

    color: #ff6b5b;

    font-size: 14px;
}

.nx-action-message strong {
    display: block;

    margin-bottom: 3px;

    color: #23394c;

    font-size: 12px;
    font-weight: 700;
}

.nx-action-message span {
    display: block;

    color: #8393a1;

    font-size: 10px;
}


/* ============================================================
   PRIMARY BUTTON
   ============================================================ */

.nx-primary-action {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 12px;

    min-height: 39px;

    padding: 0 17px;

    border: 0;
    border-radius: 9px;

    background:
        linear-gradient(
            135deg,
            #ff7667,
            #ff6252
        );

    color: #ffffff;

    font-size: 11px;
    font-weight: 750;

    cursor: pointer;

    box-shadow:
        0 6px 14px rgba(255, 107, 91, 0.20);

    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease;
}

.nx-primary-action:hover {
    transform: translateY(-1px);

    box-shadow:
        0 9px 20px rgba(255, 107, 91, 0.27);
}

.nx-primary-action i {
    font-size: 10px;
}


/* APPLIED */

.nx-applied-state {
    display: flex;
    align-items: center;
    gap: 11px;

    padding-right: 8px;
}

.nx-applied-check {
    width: 34px;
    height: 34px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: #e9f7ef;

    color: #3ca36b;

    font-size: 12px;
}

.nx-applied-state strong,
.nx-applied-state span {
    display: block;
}

.nx-applied-state strong {
    margin-bottom: 2px;

    color: #253d50;

    font-size: 11px;
}

.nx-applied-state div span {
    color: #8b9aa7;

    font-size: 9px;
}


/* ============================================================
   05. MANAGEMENT BAR
   ============================================================ */

.nx-management-bar,
.nx-interviewer-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;

    margin-bottom: 22px;
    padding: 14px 17px;

    border: 1px solid #dfe7ed;
    border-radius: 13px;

    background: #ffffff;

    box-shadow:
        0 4px 15px rgba(23, 43, 63, 0.035);
}

.nx-management-heading,
.nx-interviewer-left {
    display: flex;
    align-items: center;
    gap: 12px;
}

.nx-management-icon,
.nx-interviewer-icon {
    width: 38px;
    height: 38px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 10px;

    background: #eef4f8;

    color: #244a65;

    font-size: 13px;
}

.nx-management-heading span,
.nx-interviewer-left span {
    display: block;

    margin-bottom: 3px;

    color: #8a9aa8;

    font-size: 8px;
    font-weight: 800;

    letter-spacing: 1px;
}

.nx-management-heading strong,
.nx-interviewer-left strong {
    display: block;

    color: #243a4d;

    font-size: 11px;
}


/* MANAGEMENT ACTIONS */

.nx-management-actions {
    display: flex;
    align-items: center;
    gap: 8px;
}

.nx-secondary-action {
    display: inline-flex;
    align-items: center;
    gap: 8px;

    min-height: 34px;

    padding: 0 12px;

    border: 1px solid #dce5eb;
    border-radius: 8px;

    background: #ffffff;

    color: #395267;

    font-size: 10px;
    font-weight: 700;

    cursor: pointer;

    transition:
        border-color 0.2s ease,
        background 0.2s ease,
        color 0.2s ease;
}

.nx-secondary-action:hover {
    border-color: #b9cbd8;

    background: #f7fafc;

    color: #173b57;
}

.nx-secondary-action i {
    color: #738b9c;
}


/* ============================================================
   06. INTERVIEWER BAR
   ============================================================ */

.nx-interviewer-bar {
    border-left: 3px solid #ff6b5b;
}

.nx-interview-action {
    display: inline-flex;
    align-items: center;
    gap: 11px;

    padding: 9px 13px;

    border: 1px solid #dbe4ea;
    border-radius: 8px;

    background: #ffffff;

    color: #26445b;

    font-size: 10px;
    font-weight: 700;

    cursor: pointer;
}

.nx-interview-action:hover {
    background: #f6f9fb;
}


/* ============================================================
   07. SECTION
   ============================================================ */

.nx-section {
    margin-top: 25px;
}

.nx-section-heading {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;

    margin-bottom: 13px;
}

.nx-section-label,
.nx-panel-label {
    display: block;

    margin-bottom: 5px;

    color: #91a0ad;

    font-size: 8px;
    font-weight: 800;

    letter-spacing: 1.25px;
}

.nx-section-heading h2 {
    margin: 0;

    color: #20384c;

    font-size: 17px;
    line-height: 1.2;
    font-weight: 750;

    letter-spacing: -0.2px;
}

.nx-section-description {
    color: #93a1ad;

    font-size: 9px;
}

.nx-section-index {
    color: #b1bec8;

    font-size: 10px;
    font-weight: 800;

    letter-spacing: 1px;
}


/* ============================================================
   08. KPI CARDS
   ============================================================ */

.nx-kpi-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);

    gap: 12px;
}

.nx-kpi-card {
    position: relative;

    min-height: 138px;

    padding: 17px;

    overflow: hidden;

    border: 1px solid #e0e7ed;
    border-radius: 13px;

    background: #ffffff;

    box-shadow:
        0 4px 14px rgba(23, 43, 63, 0.035);

    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease;
}

.nx-kpi-card:hover {
    transform: translateY(-2px);

    box-shadow:
        0 9px 24px rgba(23, 43, 63, 0.07);
}

.nx-kpi-card::after {
    content: "";

    position: absolute;

    width: 80px;
    height: 80px;

    right: -38px;
    bottom: -40px;

    border-radius: 50%;

    background: rgba(31, 72, 101, 0.035);
}

.nx-kpi-highlight {
    border-color: rgba(255, 107, 91, 0.25);
}

.nx-kpi-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.nx-kpi-icon {
    width: 34px;
    height: 34px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 9px;

    font-size: 12px;
}

.nx-icon-blue {
    background: #edf5fb;
    color: #33759c;
}

.nx-icon-purple {
    background: #f1effb;
    color: #7665a8;
}

.nx-icon-orange {
    background: #fff4e9;
    color: #c57c32;
}

.nx-icon-coral {
    background: #fff0ed;
    color: #f06757;
}

.nx-kpi-label {
    color: #8e9da9;

    font-size: 8px;
    font-weight: 800;

    letter-spacing: 0.9px;
}

.nx-kpi-number {
    margin-top: 13px;

    color: #1d3548;

    font-size: 27px;
    line-height: 1;

    font-weight: 750;

    letter-spacing: -0.7px;
}

.nx-kpi-footer {
    margin-top: 8px;

    color: #91a0ac;

    font-size: 9px;
}


/* ============================================================
   09. RECRUITMENT PIPELINE
   ============================================================ */

.nx-pipeline-card {
    position: relative;

    display: grid;
    grid-template-columns: repeat(4, 1fr);

    padding: 28px 32px 25px;

    border: 1px solid #e0e7ed;
    border-radius: 14px;

    background: #ffffff;

    box-shadow:
        0 4px 14px rgba(23, 43, 63, 0.035);
}

.nx-pipeline-line {
    position: absolute;

    left: 13%;
    right: 13%;

    top: 45px;

    height: 2px;

    background:
        linear-gradient(
            90deg,
            #dce6ec,
            #dce6ec
        );

    z-index: 0;
}

.nx-pipeline-stage {
    position: relative;
    z-index: 1;

    display: flex;
    flex-direction: column;
    align-items: center;

    text-align: center;
}

.nx-stage-node {
    width: 35px;
    height: 35px;

    display: flex;
    align-items: center;
    justify-content: center;

    margin-bottom: 10px;

    border: 4px solid #ffffff;
    border-radius: 50%;

    background: #eaf1f5;

    color: #627d8e;

    font-size: 11px;

    box-shadow:
        0 0 0 1px #d6e1e8;
}

.nx-pipeline-stage strong {
    margin-bottom: 4px;

    color: #30495c;

    font-size: 10px;
    font-weight: 750;
}

.nx-pipeline-stage span {
    color: #8495a2;

    font-size: 10px;
}

.nx-stage-final .nx-stage-node {
    background: #fff0ed;

    color: #ff6b5b;

    box-shadow:
        0 0 0 1px #ffc9c2;
}


/* ============================================================
   10. TWO COLUMN CONTENT
   ============================================================ */

.nx-content-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.15fr) minmax(360px, 0.85fr);

    gap: 14px;

    margin-top: 25px;
}


/* ============================================================
   11. PANELS
   ============================================================ */

.nx-panel {
    overflow: hidden;

    border: 1px solid #e0e7ed;
    border-radius: 14px;

    background: #ffffff;

    box-shadow:
        0 4px 14px rgba(23, 43, 63, 0.035);
}

.nx-panel-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;

    padding: 18px 19px;

    border-bottom: 1px solid #e9eef2;
}

.nx-panel-header h3 {
    margin: 0;

    color: #253d50;

    font-size: 14px;
    font-weight: 750;
}

.nx-panel-number {
    color: #b5c1ca;

    font-size: 9px;
    font-weight: 800;

    letter-spacing: 1px;
}


/* ============================================================
   12. INFORMATION LIST
   ============================================================ */

.nx-info-list {
    padding: 2px 19px;
}

.nx-info-row {
    display: flex;
    align-items: center;
    justify-content: space-between;

    min-height: 52px;

    border-bottom: 1px solid #edf1f4;
}

.nx-info-row:last-child {
    border-bottom: 0;
}

.nx-info-label {
    display: flex;
    align-items: center;
    gap: 10px;

    color: #7e909e;

    font-size: 10px;
    font-weight: 600;
}

.nx-info-icon {
    width: 28px;
    height: 28px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 7px;

    background: #f4f7f9;

    color: #718798;

    font-size: 10px;
}

.nx-info-row strong {
    max-width: 52%;

    overflow: hidden;
    text-overflow: ellipsis;

    color: #294256;

    font-size: 10px;
    font-weight: 700;

    text-align: right;
}


/* ============================================================
   13. REQUIREMENTS
   ============================================================ */

.nx-requirements {
    padding: 12px 19px;
}

.nx-requirement {
    display: flex;
    align-items: center;
    gap: 11px;

    padding: 11px 0;

    border-bottom: 1px solid #edf1f4;
}

.nx-requirement:last-child {
    border-bottom: 0;
}

.nx-requirement-icon {
    width: 30px;
    height: 30px;

    flex-shrink: 0;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 8px;

    background: #f1f5f8;

    color: #496a80;

    font-size: 10px;
}

.nx-requirement span,
.nx-requirement strong {
    display: block;
}

.nx-requirement span {
    margin-bottom: 3px;

    color: #8999a6;

    font-size: 9px;
}

.nx-requirement strong {
    color: #2c4559;

    font-size: 10px;
    font-weight: 700;
}


/* ============================================================
   STUDENT ELIGIBILITY
   ============================================================ */

.nx-student-eligibility {
    display: flex;
    align-items: center;
    gap: 11px;

    margin: 3px 19px 18px;
    padding: 11px 12px;

    border-radius: 9px;

    background: #f5f8fa;
}

.nx-eligibility-status-icon {
    width: 31px;
    height: 31px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 8px;

    background: #e7f6ed;

    color: #3a9c68;

    font-size: 11px;
}

.nx-student-eligibility span,
.nx-student-eligibility strong {
    display: block;
}

.nx-student-eligibility span {
    margin-bottom: 2px;

    color: #8999a6;

    font-size: 8px;
    font-weight: 800;

    letter-spacing: 0.8px;
}

.nx-student-eligibility strong {
    color: #2e4b5e;

    font-size: 10px;
}

.nx-not-eligible {
    background: #fff6f4;
}

.nx-not-eligible .nx-eligibility-status-icon {
    background: #ffe9e5;
    color: #e96758;
}


/* ============================================================
   14. STUDENT JOURNEY
   ============================================================ */

.nx-journey-card {
    display: flex;
    align-items: center;

    padding: 25px 28px;

    border: 1px solid #e0e7ed;
    border-radius: 14px;

    background: #ffffff;

    box-shadow:
        0 4px 14px rgba(23, 43, 63, 0.035);
}

.nx-journey-step {
    display: flex;
    align-items: center;
    gap: 10px;

    flex: 1;

    min-width: 0;
}

.nx-journey-node {
    width: 35px;
    height: 35px;

    flex-shrink: 0;

    display: flex;
    align-items: center;
    justify-content: center;

    border: 1px solid #d9e3e9;
    border-radius: 50%;

    background: #f5f8fa;

    color: #718797;

    font-size: 10px;
}

.nx-step-complete .nx-journey-node {
    border-color: #ffb5ac;

    background: #fff0ed;

    color: #ff6b5b;
}

.nx-journey-step strong,
.nx-journey-step span {
    display: block;
}

.nx-journey-step strong {
    margin-bottom: 3px;

    color: #30495b;

    font-size: 10px;
}

.nx-journey-step span {
    color: #91a0ab;

    font-size: 8px;
}

.nx-journey-connector {
    width: 40px;
    height: 1px;

    flex-shrink: 0;

    margin: 0 10px;

    background: #dce5eb;
}


/* ============================================================
   15. MANAGEMENT OPERATION CARDS
   ============================================================ */

.nx-management-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);

    gap: 12px;
}

.nx-operation-card {
    position: relative;

    display: flex;
    align-items: center;
    gap: 14px;

    min-height: 126px;

    padding: 18px;

    border: 1px solid #e0e7ed;
    border-radius: 13px;

    background: #ffffff;

    cursor: pointer;

    box-shadow:
        0 3px 12px rgba(23, 43, 63, 0.025);

    transition:
        transform 0.2s ease,
        border-color 0.2s ease,
        box-shadow 0.2s ease;
}

.nx-operation-card:hover {
    transform: translateY(-2px);

    border-color: #cbd9e2;

    box-shadow:
        0 9px 22px rgba(23, 43, 63, 0.065);
}

.nx-operation-icon {
    width: 42px;
    height: 42px;

    flex-shrink: 0;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 11px;

    background: #edf4f8;

    color: #2d5872;

    font-size: 13px;
}

.nx-operation-content {
    min-width: 0;

    padding-right: 20px;
}

.nx-operation-content span {
    display: block;

    margin-bottom: 4px;

    color: #94a2ad;

    font-size: 7px;
    font-weight: 800;

    letter-spacing: 1px;
}

.nx-operation-content strong {
    display: block;

    margin-bottom: 5px;

    color: #284257;

    font-size: 11px;
}

.nx-operation-content p {
    margin: 0;

    color: #8999a6;

    font-size: 9px;
    line-height: 1.45;
}

.nx-operation-arrow {
    position: absolute;

    right: 17px;
    top: 50%;

    transform: translateY(-50%);

    color: #9babb7;

    font-size: 10px;

    transition:
        color 0.2s ease,
        transform 0.2s ease;
}

.nx-operation-card:hover .nx-operation-arrow {
    color: #ff6b5b;

    transform:
        translate(3px, -50%);
}


/* ============================================================
   16. INTERVIEWER WORKSPACE
   ============================================================ */

.nx-interviewer-workspace {
    display: grid;
    grid-template-columns: repeat(3, 1fr) auto;
    align-items: center;
    gap: 0;

    overflow: hidden;

    border: 1px solid #e0e7ed;
    border-radius: 14px;

    background: #ffffff;

    box-shadow:
        0 4px 14px rgba(23, 43, 63, 0.035);
}

.nx-interviewer-stat {
    padding: 19px 23px;

    border-right: 1px solid #e7edf1;
}

.nx-interviewer-stat span,
.nx-interviewer-stat strong {
    display: block;
}

.nx-interviewer-stat span {
    margin-bottom: 7px;

    color: #92a1ad;

    font-size: 8px;
    font-weight: 800;

    letter-spacing: 1px;
}

.nx-interviewer-stat strong {
    color: #253e51;

    font-size: 23px;
    font-weight: 750;
}

.nx-interviewer-workspace .nx-primary-action {
    margin: 0 17px;
}


/* ============================================================
   17. TIMELINE
   ============================================================ */

.nx-timeline {
    position: relative;

    display: grid;
    grid-template-columns: repeat(5, 1fr);

    padding: 8px 12px 10px;

    border: 1px solid #e0e7ed;
    border-radius: 14px;

    background: #ffffff;

    box-shadow:
        0 4px 14px rgba(23, 43, 63, 0.035);
}

.nx-timeline::before {
    content: "";

    position: absolute;

    left: 9%;
    right: 9%;

    top: 29px;

    height: 1px;

    background: #dce5eb;
}

.nx-timeline-item {
    position: relative;
    z-index: 1;

    padding: 8px 14px 15px;

    text-align: center;
}

.nx-timeline-marker {
    width: 35px;
    height: 35px;

    display: flex;
    align-items: center;
    justify-content: center;

    margin: 0 auto 11px;

    border: 5px solid #ffffff;
    border-radius: 50%;

    background: #edf2f5;

    color: #8293a0;

    font-size: 9px;

    box-shadow:
        0 0 0 1px #d8e2e8;
}

.nx-timeline-complete .nx-timeline-marker {
    background: #e9f6ef;

    color: #3b9c68;

    box-shadow:
        0 0 0 1px #bde1cd;
}

.nx-timeline-active .nx-timeline-marker {
    background: #fff0ed;

    color: #ff6b5b;

    box-shadow:
        0 0 0 1px #ffc1b8;
}

.nx-timeline-content span,
.nx-timeline-content strong,
.nx-timeline-content small {
    display: block;
}

.nx-timeline-content span {
    margin-bottom: 4px;

    color: #96a4ae;

    font-size: 7px;
    font-weight: 800;

    letter-spacing: 0.9px;
}

.nx-timeline-content strong {
    margin-bottom: 4px;

    color: #30495c;

    font-size: 9px;
    font-weight: 700;
}

.nx-timeline-content small {
    color: #9aa8b2;

    font-size: 8px;
}


/* ============================================================
   18. FOOTER
   ============================================================ */

.nx-drive-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;

    margin-top: 32px;
    padding-top: 18px;

    border-top: 1px solid #dfe6eb;

    color: #9aa8b3;

    font-size: 8px;
}

.nx-footer-left {
    display: flex;
    align-items: center;
    gap: 10px;
}

.nx-footer-label {
    color: #6f8391;

    font-weight: 800;

    letter-spacing: 0.9px;
}

.nx-footer-right {
    display: flex;
    align-items: center;
    gap: 5px;
}

.nx-footer-right strong {
    color: #738694;

    font-family:
        "SFMono-Regular",
        Consolas,
        monospace;
}


/* ============================================================
   19. BUTTON / LINK SAFETY
   ============================================================ */

.nx-drive-workspace button,
.nx-drive-workspace a {
    outline: none;
}

.nx-drive-workspace button:focus,
.nx-drive-workspace a:focus {
    outline: 2px solid rgba(255, 107, 91, 0.28);
    outline-offset: 2px;
}


/* ============================================================
   20. HOVER MICRO INTERACTIONS
   ============================================================ */

.nx-info-row:hover .nx-info-icon {
    background: #eef4f7;

    color: #345a72;
}

.nx-requirement:hover .nx-requirement-icon {
    background: #edf4f8;

    color: #315a72;
}


/* ============================================================
   21. RESPONSIVE — LARGE TABLETS
   ============================================================ */

@media (max-width: 1180px) {

    .nexora-main {
        padding: 28px 28px 60px;
    }

    .nx-header-content {
        padding: 27px 27px 24px;
    }

    .nx-header-metric {
        padding: 13px 17px;
    }

    .nx-content-grid {
        grid-template-columns: 1fr;
    }

    .nx-kpi-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .nx-management-grid {
        grid-template-columns: repeat(2, 1fr);
    }

}


/* ============================================================
   22. TABLET
   ============================================================ */

@media (max-width: 900px) {

    .nexora-main {
        padding: 22px 20px 50px;
    }

    .nx-page-context {
        display: none;
    }

    .nx-header-content {
        flex-direction: column;
        gap: 22px;
    }

    .nx-header-status-area {
        width: 100%;

        flex-direction: row;
        align-items: center;
        justify-content: space-between;

        padding-left: 0;
    }

    .nx-header-id {
        align-items: flex-start;
    }

    .nx-header-metrics {
        grid-template-columns: repeat(2, 1fr);
    }

    .nx-header-metric:nth-child(2) {
        border-right: 0;
    }

    .nx-header-metric:nth-child(-n+2) {
        border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    }

    .nx-pipeline-card {
        padding-left: 18px;
        padding-right: 18px;
    }

    .nx-timeline {
        grid-template-columns: 1fr;
        gap: 0;
        padding: 15px;
    }

    .nx-timeline::before {
        left: 32px;
        right: auto;

        top: 28px;
        bottom: 28px;

        width: 1px;
        height: auto;
    }

    .nx-timeline-item {
        display: flex;
        align-items: center;

        padding: 9px 10px;

        text-align: left;
    }

    .nx-timeline-marker {
        margin: 0 15px 0 0;
    }

}


/* ============================================================
   23. MOBILE
   ============================================================ */

@media (max-width: 680px) {

    .nexora-main {
        padding: 16px 13px 45px;
    }

    .nx-page-topbar {
        margin-bottom: 13px;
    }

    .nx-back-link {
        font-size: 11px;
    }

    .nx-drive-header {
        border-radius: 14px;
    }

    .nx-header-content {
        padding: 22px 19px;
    }

    .nx-company-section {
        align-items: flex-start;
        gap: 13px;
    }

    .nx-company-logo {
        width: 51px;
        height: 51px;

        border-radius: 12px;

        font-size: 18px;
    }

    .nx-company-copy h1 {
        font-size: 23px;
    }

    .nx-drive-title {
        font-size: 11px;
    }

    .nx-drive-meta {
        flex-wrap: wrap;

        font-size: 9px;
    }

    .nx-header-status-area {
        align-items: flex-start;
    }

    .nx-header-metrics {
        grid-template-columns: 1fr;
    }

    .nx-header-metric {
        border-right: 0;

        border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    }

    .nx-header-metric:last-child {
        border-bottom: 0;
    }

    .nx-student-actionbar,
    .nx-management-bar,
    .nx-interviewer-bar {
        flex-direction: column;
        align-items: stretch;
    }

    .nx-primary-action,
    .nx-interview-action {
        width: 100%;
    }

    .nx-management-actions {
        display: grid;
        grid-template-columns: 1fr;

        width: 100%;
    }

    .nx-secondary-action {
        justify-content: center;
    }

    .nx-kpi-grid {
        grid-template-columns: 1fr 1fr;

        gap: 8px;
    }

    .nx-kpi-card {
        min-height: 122px;

        padding: 13px;
    }

    .nx-kpi-number {
        font-size: 23px;
    }

    .nx-pipeline-card {
        grid-template-columns: 1fr;

        gap: 18px;

        padding: 20px;
    }

    .nx-pipeline-line {
        left: 37px;
        right: auto;

        top: 37px;
        bottom: 37px;

        width: 1px;
        height: auto;
    }

    .nx-pipeline-stage {
        flex-direction: row;

        gap: 12px;

        text-align: left;
    }

    .nx-stage-node {
        margin: 0;
    }

    .nx-pipeline-stage strong {
        margin-bottom: 2px;
    }

    .nx-content-grid {
        grid-template-columns: 1fr;
    }

    .nx-management-grid {
        grid-template-columns: 1fr;
    }

    .nx-journey-card {
        flex-direction: column;

        align-items: stretch;

        gap: 0;

        padding: 18px;
    }

    .nx-journey-step {
        flex: none;
    }

    .nx-journey-connector {
        width: 1px;
        height: 22px;

        margin: 0 0 0 17px;
    }

    .nx-interviewer-workspace {
        grid-template-columns: 1fr;
    }

    .nx-interviewer-stat {
        border-right: 0;
        border-bottom: 1px solid #e7edf1;
    }

    .nx-interviewer-workspace .nx-primary-action {
        margin: 15px;
        width: calc(100% - 30px);
    }

    .nx-drive-footer {
        flex-direction: column;
        align-items: flex-start;
        gap: 8px;
    }

}


/* ============================================================
   24. SMALL MOBILE
   ============================================================ */

@media (max-width: 430px) {

    .nx-kpi-grid {
        grid-template-columns: 1fr;
    }

    .nx-section-heading {
        align-items: flex-start;
        gap: 10px;
    }

    .nx-section-description {
        display: none;
    }

    .nx-company-copy h1 {
        font-size: 21px;
    }

    .nx-header-id {
        display: none;
    }

}


/* ============================================================
   25. SERVICENOW PORTAL SHELL COMPATIBILITY
   ============================================================ */

/*
   Important:
   Do NOT use fixed positioning, negative margins or viewport
   hacks here. ServiceNow already owns the portal shell/sidebar.
*/

.nexora-main .navbar,
.nexora-main .nav,
.nexora-main .panel {
    box-shadow: none;
}


/* Prevent accidental Bootstrap panel styling */

.nexora-main .panel {
    border: 0;
    background: transparent;
}


/* Remove unwanted default anchor styling */

.nexora-main a:hover,
.nexora-main a:focus {
    text-decoration: none;
}


/* ============================================================
   END — NEXORA PLACEMENT DRIVE WORKSPACE CSS
   ============================================================ */

sp_widget.script:
(function() {

    /* ============================================================
       NEXORA — PLACEMENT DRIVE DETAILS
       SERVER SCRIPT

       APPLICATION:
       x_2065256_colleg_0_

       MAIN TABLE:
       x_2065256_colleg_0_placement_drive

       ROLES:
       ------------------------------------------------------------
       1. Student
       2. Placement Officer
       3. Placement Admin
       4. Interviewer
       5. Company HR
       6. System Administrator

       SELECTION LOGIC:
       ------------------------------------------------------------
       Interview Status = Completed
       AND
       Interview Result = Pass
       =
       Selected Candidate
       ============================================================ */


    /* ============================================================
       01. DEFAULT DATA
       ============================================================ */

    data.error = '';
    data.loaded = false;

    data.drive = {};

    data.isStudent = false;
    data.isPlacementOfficer = false;
    data.isPlacementAdmin = false;
    data.isInterviewer = false;
    data.isCompanyHR = false;
    data.isAdmin = false;

    data.canManage = false;
    data.canInterview = false;

    data.hasApplied = false;
    data.applicationId = '';
    data.applicationStatus = '';
    data.eligibilityStatus = '';

    data.studentEligible = false;
    data.studentEligibilityMessage = '';

    data.applicationCount = 0;
    data.shortlistedCount = 0;
    data.interviewCount = 0;
    data.selectedCount = 0;
    data.offeredCount = 0;

    data.pipeline = {
        applied: 0,
        shortlisted: 0,
        interview: 0,
        selected: 0
    };

    data.operations = [];

    data.timeline = [];


    /* ============================================================
       02. LOGGED-IN USER
       ============================================================ */

    var userId = gs.getUserID();

    data.userId = userId;
    data.userName = gs.getUserDisplayName();
    data.userEmail = gs.getUser().getEmail();


    /* ============================================================
       03. ROLE DETECTION
       ============================================================ */

    data.isAdmin = gs.hasRole('admin');

    data.isPlacementAdmin =
        gs.hasRole(
            'x_2065256_colleg_0.placement_admin'
        );

    data.isPlacementOfficer =
        gs.hasRole(
            'x_2065256_colleg_0.placement_officer'
        );

    data.isInterviewer =
        gs.hasRole(
            'x_2065256_colleg_0.interviewer'
        );

    data.isCompanyHR =
        gs.hasRole(
            'x_2065256_colleg_0.company_hr'
        );


    /*
     * A user who has none of the management roles is treated
     * as a student for portal purposes.
     */

    data.isStudent =
        !data.isAdmin &&
        !data.isPlacementAdmin &&
        !data.isPlacementOfficer &&
        !data.isInterviewer &&
        !data.isCompanyHR;


    /* ============================================================
       04. PERMISSIONS
       ============================================================ */

    data.canManage =
        data.isAdmin ||
        data.isPlacementAdmin ||
        data.isPlacementOfficer;

    data.canInterview =
        data.isAdmin ||
        data.isPlacementAdmin ||
        data.isPlacementOfficer ||
        data.isInterviewer ||
        data.isCompanyHR;


    /* ============================================================
       05. GET DRIVE ID
       ============================================================ */

    var driveId = '';

    if (input && input.drive_id) {
        driveId = input.drive_id;
    }

    if (!driveId && $sp.getParameter('id')) {
        driveId = $sp.getParameter('id');
    }

    if (!driveId && $sp.getParameter('sys_id')) {
        driveId = $sp.getParameter('sys_id');
    }


    /* ============================================================
       06. VALIDATE DRIVE ID
       ============================================================ */

    if (!driveId) {

        data.error =
            'Placement drive information is not available.';

        return;
    }


    /* ============================================================
       07. LOAD PLACEMENT DRIVE
       ============================================================ */

    var driveGR = new GlideRecord(
        'x_2065256_colleg_0_placement_drive'
    );

    if (!driveGR.get(driveId)) {

        data.error =
            'The requested placement drive could not be found.';

        return;
    }


    /* ============================================================
       08. BASIC DRIVE INFORMATION
       ============================================================ */

    data.drive.sysId =
        driveGR.getUniqueValue();

    data.drive.company =
        driveGR.getDisplayValue('company');

    data.drive.driveName =
        driveGR.getDisplayValue('drive_name');


    /*
     * Company initial
     */

    if (data.drive.company) {

        data.drive.companyInitial =
            data.drive.company
                .substring(0, 1)
                .toUpperCase();

    } else {

        data.drive.companyInitial = 'N';

    }


    /* ============================================================
       09. DRIVE META INFORMATION
       ============================================================ */

    data.drive.package =
        driveGR.getDisplayValue('package');

    data.drive.driveDate =
        driveGR.getDisplayValue('drive_date');

    data.drive.venue =
        driveGR.getDisplayValue('venue');

    data.drive.status =
        driveGR.getDisplayValue('status');

    data.drive.registrationDeadline =
        driveGR.getDisplayValue(
            'registration_deadline'
        );


    /* ============================================================
       10. DESCRIPTION
       ============================================================ */

    data.drive.description =
        driveGR.getDisplayValue('description');


    if (!data.drive.description) {

        data.drive.description =
            'This placement drive is available for eligible students based on the academic and eligibility requirements configured by the placement team.';

    }


    /* ============================================================
       11. ELIGIBILITY INFORMATION
       ============================================================ */

    data.drive.minimumCGPA =
        driveGR.getDisplayValue('minimum_cgpa');

    data.drive.backlogs =
        driveGR.getDisplayValue('backlogs');

    data.drive.branch =
        driveGR.getDisplayValue('eligible_branch');

    data.drive.batch =
        driveGR.getDisplayValue('eligible_batch');


    /* ============================================================
       12. DRIVE STATUS
       ============================================================ */

    var statusValue =
        driveGR.getValue('status');

    var statusDisplay =
        driveGR.getDisplayValue('status');


    data.drive.isActive =
        statusValue == 'active' ||
        statusDisplay == 'Active';

    data.drive.isClosed =
        statusValue == 'closed' ||
        statusDisplay == 'Closed';


    /* ============================================================
       13. REGISTRATION DEADLINE CHECK
       ============================================================ */

    data.drive.deadlinePassed = false;

    if (driveGR.getValue('registration_deadline')) {

        var deadline =
            new GlideDateTime(
                driveGR.getValue(
                    'registration_deadline'
                )
            );

        var now =
            new GlideDateTime();

        data.drive.deadlinePassed =
            deadline.getNumericValue() <
            now.getNumericValue();
    }


    /* ============================================================
       14. LOAD APPLICATION DATA
       ============================================================ */

    var applicationGR =
        new GlideRecord(
            'x_2065256_colleg_0_application'
        );


    /*
     * Student:
     * Only inspect the logged-in student's applications.
     *
     * Management:
     * Load all applications for this drive.
     */

    if (data.isStudent) {

        applicationGR.addQuery(
            'drive',
            driveGR.getUniqueValue()
        );


        /*
         * Application -> Student -> User
         */

        applicationGR.addQuery(
            'student.user',
            userId
        );

    } else {

        applicationGR.addQuery(
            'drive',
            driveGR.getUniqueValue()
        );

    }

    applicationGR.query();


    /* ============================================================
       15. PROCESS APPLICATIONS
       ============================================================ */

    while (applicationGR.next()) {

        var appStatus =
            applicationGR.getDisplayValue('status');

        var appStatusValue =
            applicationGR.getValue('status');


        /* --------------------------------------------------------
           STUDENT APPLICATION
           -------------------------------------------------------- */

        if (data.isStudent) {

            data.hasApplied = true;

            data.applicationId =
                applicationGR.getUniqueValue();

            data.applicationStatus =
                appStatus;

            data.eligibilityStatus =
                applicationGR.getDisplayValue(
                    'eligibility_status'
                );


            /*
             * Eligibility
             */

            var eligibility =
                applicationGR.getDisplayValue(
                    'eligibility_status'
                );

            data.studentEligible =
                eligibility == 'Eligible' ||
                eligibility == 'eligible' ||
                eligibility == 'Yes';


            if (data.studentEligible) {

                data.studentEligibilityMessage =
                    'You are eligible for this placement drive.';

            } else {

                data.studentEligibilityMessage =
                    'Eligibility is currently pending or not satisfied.';

            }

        }


        /* --------------------------------------------------------
           APPLICATION COUNT
           -------------------------------------------------------- */

        data.applicationCount++;


        /* --------------------------------------------------------
           SHORTLISTED COUNT
           -------------------------------------------------------- */

        if (
            appStatus == 'Shortlisted' ||
            appStatusValue == 'shortlisted'
        ) {

            data.shortlistedCount++;

            data.pipeline.shortlisted++;

        }


        /* --------------------------------------------------------
           INTERVIEW PIPELINE
           -------------------------------------------------------- */

        if (
            appStatus == 'Interview Scheduled' ||
            appStatus == 'Interview' ||
            appStatusValue == 'interview_scheduled'
        ) {

            data.interviewCount++;

            data.pipeline.interview++;

        }


        /* --------------------------------------------------------
           IMPORTANT:
           DO NOT COUNT SELECTED FROM APPLICATION STATUS

           Selection is now determined from:

           Interview.status = Completed
           AND
           Interview.result = Pass
           -------------------------------------------------------- */


        /* --------------------------------------------------------
           OFFERED
           -------------------------------------------------------- */

        if (
            appStatus == 'Offered' ||
            appStatusValue == 'offered'
        ) {

            data.offeredCount++;

        }

    }


    /* ============================================================
       16. INTERVIEW COUNT

       IMPORTANT:
       The Interview table is the authoritative source for
       interview records.

       This keeps the details page aligned with actual
       Interview records.
       ============================================================ */

    var interviewCountGR =
        new GlideRecord(
            'x_2065256_colleg_0_interview'
        );

    interviewCountGR.addQuery(
        'drive',
        driveGR.getUniqueValue()
    );

    interviewCountGR.query();


    /*
     * Count actual Interview records.
     */

    var actualInterviewCount = 0;

    while (interviewCountGR.next()) {

        actualInterviewCount++;

    }


    /*
     * If Interview records exist, use the actual Interview
     * table count.
     *
     * Otherwise retain the application-based interview count.
     */

    if (actualInterviewCount > 0) {

        data.interviewCount =
            actualInterviewCount;

        data.pipeline.interview =
            actualInterviewCount;

    }


    /* ============================================================
       17. SELECTED COUNT

       BUSINESS RULE:
       ------------------------------------------------------------
       Interview Status = Completed
       AND
       Interview Result = Pass

       =

       Selected Candidate
       ============================================================ */

    var selectedInterviewGR =
        new GlideRecord(
            'x_2065256_colleg_0_interview'
        );

    selectedInterviewGR.addQuery(
        'drive',
        driveGR.getUniqueValue()
    );

    selectedInterviewGR.query();


    /*
     * Prevent duplicate counting if the same Application has
     * multiple completed/pass interview records.
     */

    var selectedApplicationIds = {};


    while (selectedInterviewGR.next()) {

        var interviewStatusDisplay =
            selectedInterviewGR.getDisplayValue(
                'status'
            ) || '';

        var interviewStatusValue =
            selectedInterviewGR.getValue(
                'status'
            ) || '';


        var interviewResultDisplay =
            selectedInterviewGR.getDisplayValue(
                'result'
            ) || '';

        var interviewResultValue =
            selectedInterviewGR.getValue(
                'result'
            ) || '';


        /*
         * Normalize values.
         */

        var normalizedInterviewStatus =
            String(
                interviewStatusDisplay
            )
            .toLowerCase()
            .replace(/[\s_-]+/g, '');


        var normalizedInterviewStatusValue =
            String(
                interviewStatusValue
            )
            .toLowerCase()
            .replace(/[\s_-]+/g, '');


        var normalizedInterviewResult =
            String(
                interviewResultDisplay
            )
            .toLowerCase()
            .replace(/[\s_-]+/g, '');


        var normalizedInterviewResultValue =
            String(
                interviewResultValue
            )
            .toLowerCase()
            .replace(/[\s_-]+/g, '');


        /*
         * COMPLETED
         *
         * Supports both display value and internal value.
         */

        var isCompleted =
            normalizedInterviewStatus ==
                'completed' ||

            normalizedInterviewStatusValue ==
                'completed';


        /*
         * PASS
         *
         * Supports:
         * Pass
         * Passed
         * pass
         * passed
         *
         * through both display and internal values.
         */

        var isPassed =
            normalizedInterviewResult ==
                'pass' ||

            normalizedInterviewResult ==
                'passed' ||

            normalizedInterviewResultValue ==
                'pass' ||

            normalizedInterviewResultValue ==
                'passed';


        /*
         * FINAL SELECTION CONDITION
         */

        if (
            isCompleted &&
            isPassed
        ) {

            /*
             * Get Application reference.
             */

            var selectedApplicationId =
                selectedInterviewGR.getValue(
                    'application'
                );


            /*
             * If Application is populated,
             * count each candidate only once.
             */

            if (selectedApplicationId) {

                if (
                    !selectedApplicationIds[
                        selectedApplicationId
                    ]
                ) {

                    selectedApplicationIds[
                        selectedApplicationId
                    ] = true;

                    data.selectedCount++;

                }

            } else {

                /*
                 * Fallback:
                 * If Application reference is unexpectedly
                 * empty, still count the completed/pass
                 * interview record.
                 */

                data.selectedCount++;

            }

        }

    }


    /* ============================================================
       18. SELECTED PIPELINE
       ============================================================ */

    data.pipeline.selected =
        data.selectedCount;


    /* ============================================================
       19. APPLICATION PIPELINE
       ============================================================ */

    data.pipeline.applied =
        data.applicationCount;


    /* ============================================================
       20. OPERATION CARDS
       ============================================================ */

    if (data.canManage) {

        data.operations.push({

            type: 'edit',

            title:
                'Edit Placement Drive',

            description:
                'Update drive configuration, eligibility, scheduling and registration details.',

            icon:
                'fa-pencil',

            action:
                'edit'

        });


        data.operations.push({

            type: 'applications',

            title:
                'Manage Applications',

            description:
                'Review student applications, eligibility and application status.',

            icon:
                'fa-users',

            action:
                'applications'

        });


        data.operations.push({

            type: 'interviews',

            title:
                'Manage Interviews',

            description:
                'Schedule interviews and manage candidate interview progress.',

            icon:
                'fa-calendar',

            action:
                'interviews'

        });


        data.operations.push({

            type: 'statistics',

            title:
                'Placement Analytics',

            description:
                'View application, shortlist, interview and selection statistics.',

            icon:
                'fa-bar-chart',

            action:
                'statistics'

        });

    }


    /* ============================================================
       21. INTERVIEWER OPERATIONS
       ============================================================ */

    if (
        data.canInterview &&
        !data.canManage
    ) {

        data.operations.push({

            type:
                'interviews',

            title:
                'My Interviews',

            description:
                'Review assigned interviews and submit candidate evaluations.',

            icon:
                'fa-calendar-check-o',

            action:
                'interviews'

        });

    }


    /* ============================================================
       22. STUDENT JOURNEY
       ============================================================ */

    data.journey = [];


    /*
     * STEP 1 — APPLICATION
     */

    data.journey.push({

        key:
            'application',

        title:
            'Application',

        description:
            data.hasApplied
                ? 'Application submitted'
                : 'Not applied',

        complete:
            data.hasApplied,

        icon:
            'fa-file-text-o'

    });


    /*
     * STEP 2 — SHORTLIST
     */

    var isShortlisted =
        data.applicationStatus ==
            'Shortlisted';


    data.journey.push({

        key:
            'shortlisted',

        title:
            'Shortlisted',

        description:
            isShortlisted
                ? 'Candidate shortlisted'
                : 'Awaiting shortlist',

        complete:
            isShortlisted,

        icon:
            'fa-check'

    });


    /*
     * STEP 3 — INTERVIEW
     */

    var isInterview =
        data.applicationStatus ==
            'Interview Scheduled' ||

        data.applicationStatus ==
            'Interview';


    data.journey.push({

        key:
            'interview',

        title:
            'Interview',

        description:
            isInterview
                ? 'Interview scheduled'
                : 'Interview pending',

        complete:
            isInterview,

        icon:
            'fa-comments-o'

    });


    /*
     * STEP 4 — SELECTION

       IMPORTANT:
       Student selection is also determined from
       Completed + Pass Interview logic.

       For the student's current application,
       check whether there is a completed/pass interview.
    */

    var studentSelected =
        false;


    if (
        data.isStudent &&
        data.applicationId
    ) {

        var studentSelectionGR =
            new GlideRecord(
                'x_2065256_colleg_0_interview'
            );

        studentSelectionGR.addQuery(
            'application',
            data.applicationId
        );

        studentSelectionGR.query();


        while (
            studentSelectionGR.next()
        ) {

            var studentInterviewStatus =
                (
                    studentSelectionGR
                        .getDisplayValue('status') ||
                    ''
                )
                .toLowerCase()
                .replace(/[\s_-]+/g, '');


            var studentInterviewResult =
                (
                    studentSelectionGR
                        .getDisplayValue('result') ||
                    ''
                )
                .toLowerCase()
                .replace(/[\s_-]+/g, '');


            if (
                studentInterviewStatus ==
                    'completed' &&

                (
                    studentInterviewResult ==
                        'pass' ||

                    studentInterviewResult ==
                        'passed'
                )
            ) {

                studentSelected = true;

                break;

            }

        }

    }


    /*
     * Also support management-side selected state
     * when Application Status has already been updated
     * by the existing Business Rule.
     */

    if (
        data.applicationStatus ==
            'Selected' ||

        data.applicationStatus ==
            'Offered'
    ) {

        studentSelected = true;

    }


    data.journey.push({

        key:
            'selection',

        title:
            'Selection',

        description:
            studentSelected
                ? 'Candidate selected'
                : 'Selection pending',

        complete:
            studentSelected,

        icon:
            'fa-trophy'

    });


    /* ============================================================
       23. TIMELINE
       ============================================================ */

    data.timeline = [

        {

            key:
                'created',

            label:
                'DRIVE',

            title:
                'Drive Created',

            description:
                data.drive.driveDate ||
                'Scheduled',

            icon:
                'fa-briefcase',

            state:
                'complete'

        },


        {

            key:
                'registration',

            label:
                'REGISTRATION',

            title:
                'Applications Open',

            description:
                data.drive.registrationDeadline
                    ? 'Until ' +
                      data.drive.registrationDeadline
                    : 'Open',

            icon:
                'fa-pencil-square-o',

            state:
                data.drive.deadlinePassed
                    ? 'complete'
                    : 'active'

        },


        {

            key:
                'screening',

            label:
                'SCREENING',

            title:
                'Application Review',

            description:
                data.shortlistedCount +
                ' shortlisted',

            icon:
                'fa-filter',

            state:
                data.shortlistedCount > 0
                    ? 'active'
                    : 'pending'

        },


        {

            key:
                'interview',

            label:
                'INTERVIEW',

            title:
                'Interview Stage',

            description:
                data.interviewCount +
                ' interviews',

            icon:
                'fa-comments-o',

            state:
                data.interviewCount > 0
                    ? 'active'
                    : 'pending'

        },


        {

            key:
                'selection',

            label:
                'RESULT',

            title:
                'Final Selection',

            description:
                data.selectedCount +
                ' selected',

            icon:
                'fa-trophy',

            state:
                data.selectedCount > 0
                    ? 'complete'
                    : 'pending'

        }

    ];


    /* ============================================================
       24. ROLE LABEL
       ============================================================ */

    if (data.isAdmin) {

        data.roleLabel =
            'System Administrator';

    } else if (
        data.isPlacementAdmin
    ) {

        data.roleLabel =
            'Placement Admin';

    } else if (
        data.isPlacementOfficer
    ) {

        data.roleLabel =
            'Placement Officer';

    } else if (
        data.isCompanyHR
    ) {

        data.roleLabel =
            'Company HR';

    } else if (
        data.isInterviewer
    ) {

        data.roleLabel =
            'Interviewer';

    } else {

        data.roleLabel =
            'Student';

    }


    /* ============================================================
       25. ACCESS LABEL
       ============================================================ */

    if (data.canManage) {

        data.drive.accessLabel =
            data.roleLabel;

    } else if (data.canInterview) {

        data.drive.accessLabel =
            data.roleLabel;

    } else {

        data.drive.accessLabel =
            'Student Access';

    }


    /* ============================================================
       26. STUDENT ACTION STATE
       ============================================================ */

    data.studentAction =
        'apply';


    if (data.hasApplied) {

        data.studentAction =
            'applied';

    } else if (
        data.drive.deadlinePassed
    ) {

        data.studentAction =
            'closed';

    } else if (
        data.drive.isClosed
    ) {

        data.studentAction =
            'closed';

    } else if (
        !data.drive.isActive
    ) {

        data.studentAction =
            'unavailable';

    }


    /* ============================================================
       27. FINAL FLAGS
       ============================================================ */

    data.showStudentActions =
        data.isStudent;

    data.showManagement =
        data.canManage;

    data.showInterviewerActions =
        data.canInterview &&
        !data.canManage;

    data.showStudentJourney =
        data.isStudent;

    data.showManagementWorkspace =
        data.canManage;

    data.showInterviewerWorkspace =
        data.isInterviewer ||
        data.isCompanyHR;


    /* ============================================================
       28. COMPLETE
       ============================================================ */

    data.loaded = true;


})();
